// === الإعدادات المركزية للعيادة وميتا وتليجرام ===
const META_ACCESS_TOKEN = 'YOUR_META_PERMANENT_ACCESS_TOKEN';
const FALLBACK_PHONE_NUMBER_ID = 'YOUR_WHATSAPP_PHONE_NUMBER_ID';
const ADMIN_EMERGENCY_PHONE = '201000000000';
const WAITLIST_WEBHOOK_URL = 'https://your-n8n-domain.example.com/webhook/appointment-cancelled';
const GOOGLE_SHEETS_WEBHOOK_URL = 'https://your-n8n-domain.example.com/webhook/clinic-sheets-sync';
const TELEGRAM_BOT_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const TELEGRAM_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
const CLINIC_NAME = 'عيادة دنتال كير لطب وزراعة الأسنان';
const CLINIC_MAPS_GPS_URL = 'https://maps.google.com/?q=30.0276,31.4913';
const GOOGLE_MAPS_REVIEW_URL = 'https://search.google.com/local/writereview?placeid=PUT_YOUR_CLINIC_PLACE_ID_HERE';

const value = $('Webhook').first().json.body?.entry?.[0]?.changes?.[0]?.value;
if (!value) return [];

if (value.statuses?.length) {
  return value.statuses.map(s => ({
    json: {
      type: 'status_update',
      wamid: s.id,
      status: s.status,
      timestamp: Number(s.timestamp || Math.floor(Date.now() / 1000)),
      recipient: String(s.recipient_id || '').replace(/^\+/, ''),
      error: s.errors?.[0] ? `${s.errors[0].code}: ${s.errors[0].title}` : null
    }
  }));
}

if (!value.messages?.length) {
  return [];
}

const contacts = value.contacts ?? [];
const isBsuid = v => /^[A-Z]{2}\./.test(v ?? '');

return value.messages.map(msg => {
  const contact = contacts.find(c => c.wa_id === msg.from || (c.user_id && c.user_id === msg.from_user_id)) ?? contacts[0];

  let rawPhone = String(msg.from || contact?.wa_id || '').trim().replace(/^\+/, '');
  if (rawPhone.startsWith('01')) {
    rawPhone = '20' + rawPhone.slice(1);
  }
  const localPhone = rawPhone.startsWith('20') ? '0' + rawPhone.slice(2) : rawPhone;
  const userId = msg.from_user_id ?? contact?.user_id ?? (isBsuid(msg.from) ? msg.from : null);
  const replyTo = (!isBsuid(rawPhone) && rawPhone) ? rawPhone : (userId || rawPhone);

  const buttonReplyId = msg.button?.payload
    ?? msg.interactive?.button_reply?.id
    ?? msg.interactive?.list_reply?.id
    ?? null;

  const buttonReplyTitle = msg.button?.text
    ?? msg.interactive?.button_reply?.title
    ?? msg.interactive?.list_reply?.title
    ?? null;

  let messageCategory = msg.type;
  let extractedText = null;

  if (msg.type === 'reaction' || msg.type === 'system') {
    messageCategory = 'silent';
    extractedText = msg.reaction?.emoji ?? 'system';
  } else if (msg.type === 'location') {
    messageCategory = 'text';
    extractedText = `المريض أرسل موقعه الحالي على الخريطة: (${msg.location?.latitude}, ${msg.location?.longitude}) وهو يسأل عن عنوان العيادة أو كيفية الوصول إليها.`;
  } else if (msg.type === 'text') {
    extractedText = (msg.text?.body || '').trim();
  } else if (buttonReplyId || buttonReplyTitle) {
    const idKey = String(buttonReplyId || '').trim();
    const titleKey = String(buttonReplyTitle || '').trim();
    const combinedKey = idKey || titleKey;

    if (combinedKey.startsWith('RATE_')) {
      messageCategory = 'rating_button';
      extractedText = combinedKey;
    } else if (combinedKey === 'DOC_AHMED' || titleKey.includes('أحمد')) {
      messageCategory = 'text';
      extractedText = 'عايز أحجز مع دكتور أحمد سامي، إيه الأيام والساعات الفاضية عنده؟';
    } else if (combinedKey === 'DOC_MARIAM' || titleKey.includes('مريم')) {
      messageCategory = 'text';
      extractedText = 'عايز أحجز مع دكتورة مريم كريم، إيه الأيام والساعات الفاضية عندها؟';
    } else if (idKey === 'CLAIM_WAITLIST') {
      messageCategory = 'action_button';
      extractedText = 'CLAIM_WAITLIST';
    } else if (idKey === 'CONFIRM_APPT') {
      messageCategory = 'action_button';
      extractedText = 'CONFIRM_APPT';
    } else if (idKey === 'CANCEL_APPT' || titleKey.includes('إلغاء') || idKey.includes('إلغاء')) {
      messageCategory = 'action_button';
      extractedText = 'CANCEL_APPT';
    } else if (titleKey.includes('تأكيد') || idKey.includes('تأكيد')) {
      messageCategory = 'action_button';
      extractedText = 'CONFIRM_OR_CLAIM_AUTO';
    } else {
      messageCategory = 'text';
      extractedText = titleKey || idKey;
    }
  }

  return {
    json: {
      phone_number_id: value.metadata?.phone_number_id || FALLBACK_PHONE_NUMBER_ID,
      meta_access_token: META_ACCESS_TOKEN,
      admin_emergency_phone: ADMIN_EMERGENCY_PHONE,
      waitlist_webhook_url: WAITLIST_WEBHOOK_URL,
      google_sheets_webhook_url: GOOGLE_SHEETS_WEBHOOK_URL,
      telegram_bot_token: TELEGRAM_BOT_TOKEN,
      telegram_chat_id: TELEGRAM_CHAT_ID,
      clinic_name: CLINIC_NAME,
      clinic_maps_gps_url: CLINIC_MAPS_GPS_URL,
      google_maps_review_url: GOOGLE_MAPS_REVIEW_URL,
      session_id: rawPhone || replyTo,
      phone: rawPhone,
      local_phone: localPhone,
      user_id: userId,
      reply_to: replyTo,
      name: contact?.profile?.name ?? 'عميلنا العزيز',
      message_id: msg.id,
      reply_to_message_id: msg.context?.id ?? null,
      received_at: msg.timestamp ? new Date(Number(msg.timestamp) * 1000).toISOString() : new Date().toISOString(),
      type: messageCategory,
      message: extractedText,
      button_action: extractedText,
      media_id: msg.image?.id ?? msg.audio?.id ?? msg.document?.id ?? null,
      caption: msg.image?.caption ?? 'بدون تعليق'
    }
  };
});

const db = $input.first().json;
const cfg = $('Clinic Config & Parse Meta').first().json;

let replyText = '';
let shouldNotifyWaitlist = false;

if (db.executed_action === 'CONFIRM_APPT') {
  if (db.newly_confirmed_id) {
    replyText = `تم تأكيد حضورك وتثبيت موعدك نهائياً بنجاح يا فندم! ✅🦷\nموعدك المسجل مع (${db.target_doctor}) يوم (${db.target_date}) الساعة (${db.target_time}).\nفي انتظار تشريفك للعيادة بكل سرور 😊🤍.`;
  } else if (db.was_already_locked && db.prev_status === 'confirmed') {
    replyText = `يا فندم حضرتك قمت بتأكيد هذا الموعد مسبقاً (${db.target_doctor} - يوم ${db.target_date} الساعة ${db.target_time}) وتم قفل أزرار هذه الرسالة لمنع التضارب 🔒🦷.\nفي انتظار تشريفك للعيادة، ولو حابب تستفسر عن أي شيء اكتب لنا رسالة نصية 😊🤍.`;
  } else if (db.was_already_locked && db.prev_status === 'cancelled') {
    replyText = `عفواً يا فندم، لقد قمت بإلغاء هذا الموعد مسبقاً وتم قفل خيارات هذه الرسالة وإتاحة الموعد لمريض آخر 🔒🦷.\nلحجز موعد جديد يرجى كتابة طلبك في رسالة نصية الآن وهنساعدك فوراً 😊🤍.`;
  } else {
    replyText = 'أهلاً بحضرتك يا فندم 🦷. لم نجد حجزاً قادماً نشطاً مسجلاً حالياً، لو حابب تحجز ميعاد جديد اكتب لنا وهنساعدك فوراً 😊🤍.';
  }
} else if (db.executed_action === 'CANCEL_APPT') {
  if (db.cancelled_appt_id) {
    shouldNotifyWaitlist = true;
    replyText = `تم إلغاء موعدك المسجل مع (${db.cancelled_doctor}) يوم (${db.cancelled_date}) الساعة (${db.cancelled_time}) بنجاح من النظام 🦷.\nنتمنى لك دوام الصحة والعافية، وتقدر تحجز في أي وقت آخر يناسبك 😊🤍.`;
  } else if (db.was_already_locked && db.prev_status === 'confirmed') {
    replyText = `عفواً يا فندم 🔒، لقد قمت بالضغط على زر (تأكيد الحضور) وتثبيت هذا الموعد مسبقاً، لذلك تم قفل زر الإلغاء في هذه الرسالة حفاظاً على دقة جدول العيادة 🦷.\nإذا طرأ ظرف طارئ وترغب في الإلغاء أو التعديل، يرجى كتابة "أريد إلغاء موعدي" في رسالة نصية الآن 😊🤍.`;
  } else if (db.was_already_locked && db.prev_status === 'cancelled') {
    replyText = `يا فندم تم إلغاء هذا الموعد مسبقاً بالفعل ولا يوجد حجز نشط لإلغائه مرة أخرى 🔒🦷.`;
  } else if (db.cancelled_wait_id) {
    replyText = 'تم إلغاء طلبك من قائمة الانتظار بنجاح يا فندم 🦷🤍.';
  } else {
    replyText = 'عفواً يا فندم، لا يوجد أي حجز قادم نشط مسجل برقم حضرتك حالياً لإلغائه 🦷.';
  }
} else if (db.executed_action === 'CLAIM_WAITLIST') {
  if (db.new_waitlist_appt_id) {
    replyText = `مبروك يا فندم! 🎉 تم نقل حجزك من قائمة الانتظار وتأكيده بنجاح في جدول العيادة مع (${db.waitlist_doctor}) يوم (${db.waitlist_date}) الساعة (${db.waitlist_time}) 🦷✨.\nفي انتظار تشريفك في الموعد المحدد 😊🤍.`;
  } else {
    replyText = 'بعتذر لحضرتك جداً يا فندم، يبدو أن مهلة الـ 15 دقيقة انتهت أو تم حجز الميعاد الشاغر بالفعل 🦷. سنبلغك فور توفر أقرب ميعاد آخر 😊🤍.';
  }
}

return [{
  json: {
    phone: cfg.phone,
    local_phone: cfg.local_phone,
    phone_number_id: cfg.phone_number_id,
    meta_access_token: cfg.meta_access_token,
    waitlist_webhook_url: cfg.waitlist_webhook_url,
    reply_text: replyText,
    should_notify_waitlist: shouldNotifyWaitlist,
    new_waitlist_appt_id: db.new_waitlist_appt_id,
    cancelled_doctor: db.cancelled_doctor,
    cancelled_date: db.cancelled_date,
    cancelled_time: db.cancelled_time
  }
}];

