const messages = $input.all();
if (messages.length === 0) {
  return [];
}

const currentTriggerMsgId = $('Clinic Config & Parse Meta').first().json.message_id;
const lastPendingMsg = messages[messages.length - 1].json;

if (lastPendingMsg.message_id && currentTriggerMsgId && lastPendingMsg.message_id !== currentTriggerMsgId) {
  return [];
}

const config = $('Clinic Config & Parse Meta').first().json;

const combinedMessage = messages
  .map(item => item.json.message_text)
  .filter(Boolean)
  .join(' ');

const messageIds = messages
  .map(item => item.json.id)
  .filter(Boolean);

if (!combinedMessage.trim()) {
  return [];
}

return [{
  json: {
    session_id: config.session_id,
    phone: config.phone,
    local_phone: config.local_phone,
    patient_profile_name: config.name,
    phone_number_id: config.phone_number_id,
    meta_access_token: config.meta_access_token,
    admin_emergency_phone: config.admin_emergency_phone,
    waitlist_webhook_url: config.waitlist_webhook_url,
    combined_message: combinedMessage,
    message_ids: messageIds
  }
}];

