const transcribed = ($input.first().json.text || '').trim();
return [{
  json: {
    transcribed_voice_text: transcribed || 'رسالة صوتية غير واضحة'
  }
}];

const item = $input.first()?.json;
if (!item || !item.id) {
  return [];
}

const cfg = $('Clinic Config & Parse Meta').first().json;
const patientName = item.patient_name || cfg.name || 'عميلنا العزيز';
const doctorName = item.doctor_name || 'الطبيب المختص';
const dateStr = item.appointment_date;
const timeStr = item.appointment_time;
const serviceType = item.service_type || 'كشف أسنان';

let cleanPhone = String(item.phone || cfg.phone || '').replace(/[^0-9]/g, '');
if (cleanPhone.startsWith('01')) {
  cleanPhone = '2' + cleanPhone;
}

const clinicName = cfg.clinic_name || 'عيادة دنتال كير لطب وزراعة الأسنان';
const prefilledWaMsg = encodeURIComponent(`أهلاً بحضرتك يا أ/ ${patientName}، بنأكد معاك حجزك في ${clinicName} مع ${doctorName} يوم ${dateStr} الساعة ${timeStr}.`);
const whatsappShortLink = `https://wa.me/${cleanPhone}?text=${prefilledWaMsg}`;

const doctorTelegramHtml =
`✅ <b>حجز موعد جديد بالعيادة! (#${item.id})</b>

👤 <b>اسم المريض:</b> ${patientName}
👨‍⚕️ <b>اسم الدكتور:</b> ${doctorName}
🦷 <b>الخدمة:</b> ${serviceType}
📅 <b>التاريخ:</b> ${dateStr}
⏰ <b>الوقت:</b> ${timeStr}
📞 <b>رقم التليفون:</b> <code>+${cleanPhone}</code>

📲 <a href="${whatsappShortLink}">اضغط هنا لمراسلة المريض على واتساب فوراً</a>`;

return [{
  json: {
    appointment_id: item.id,
    event_type: 'BOOKED',
    patient_name: patientName,
    patient_phone: cleanPhone,
    doctor_name: doctorName,
    service_type: serviceType,
    appointment_date: dateStr,
    appointment_time: timeStr,
    status: 'مؤكد (Confirmed)',
    telegram_bot_token: cfg.telegram_bot_token,
    telegram_chat_id: cfg.telegram_chat_id,
    google_sheets_webhook_url: cfg.google_sheets_webhook_url || 'https://your-n8n-domain.example.com/webhook/clinic-sheets-sync',
    doctor_telegram_html: doctorTelegramHtml
  }
}];

// فلترة المواعيد التي مر على وقتها من 4 إلى 20 ساعة (داخل نافذة الـ 24 ساعة في ميتا)
const items = $input.all();
const now = new Date();
const results = [];

for (const wrapped of items) {
  const item = wrapped.json;
  if (!item || !item.id) continue;
  const [year, month, day] = String(item.appointment_date).split('-').map(Number);
  const cleanTime = String(item.appointment_time || '05:00 PM').trim().toUpperCase();
  const match = cleanTime.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/);
  let hours = match ? parseInt(match[1], 10) : 17;
  const minutes = match ? parseInt(match[2], 10) : 0;
  const period = match ? match[3] : null;
  if (period === 'PM' && hours < 12) hours += 12;
  if (period === 'AM' && hours === 12) hours = 0;

  const apptTime = new Date(`${String(year).padStart(4,'0')}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}T${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:00+02:00`);
  const hoursSinceAppt = (now - apptTime) / (1000 * 60 * 60);

  if (hoursSinceAppt >= 4 && hoursSinceAppt <= 20) {
    let phone = String(item.patient_phone || '').replace(/[^0-9]/g, '');
    if (phone.startsWith('01')) phone = '2' + phone;
    results.push({
      json: {
        ...item,
        patient_phone: phone
      }
    });
  }
}

return results;

