const cfg = $('Clinic Config & Parse Meta').first().json;
const buttonId = String(cfg.button_action || ''); // مثل RATE_5_120
const patientPhone = cfg.phone;
const patientName = cfg.name || 'المريض';
const googleMapsReviewUrl = cfg.google_maps_review_url;

const parts = buttonId.split('_');
const score = parseInt(parts[1], 10) || 5;
const appointmentId = parseInt(parts[2], 10) || 0;

if (score >= 3) {
  // من 3 إلى 5 نجوم -> نبعت للمريض رابط تقييم Google Maps
  const replyToCustomer =
`شكراً جزيلاً لحضرتك على تقييمك الإيجابي (${score}/5)! 🌟🌸

يسعدنا ويشرفنا جداً لو شاركت تجربتك في ثواني على خرائط جوجل (Google Maps) من خلال الضغط على هذا الرابط المباشر:
${googleMapsReviewUrl}

نتمنى لك دوام الصحة والابتسامة الجميلة! 🦷✨`;

  return [{
    json: {
      score: score,
      appointment_id: appointmentId,
      patient_phone: patientPhone,
      phone_number_id: cfg.phone_number_id,
      meta_access_token: cfg.meta_access_token,
      telegram_bot_token: cfg.telegram_bot_token,
      telegram_chat_id: cfg.telegram_chat_id,
      is_low_rating_alert: false,
      customer_reply_text: replyToCustomer,
      admin_telegram_alert: ''
    }
  }];
} else {
  // 1 أو 2 نجمة -> نحجب رابط جوجل مابس ونعتذر للمريض ونبعت إنذار فوري للدكتور على تليجرام
  const replyToCustomer =
`شكراً لصراحتك معنا 🌸
نعتذر بشدة عن أي تقصير أو ملاحظة واجهتك اليوم (تقييمك: ${score}/5).

تم تحويل ملاحظتك فوراً لمدير العيادة والدكتور المختص وسنتواصل مع حضرتك شخصياً لحل المشكلة فوراً، لأن رضاك هو أولويتنا دائماً. 🦷🤍`;

  const waLink = `https://wa.me/${patientPhone}`;
  const adminAlertHtml =
`⚠️ <b>تنبيه عاجل: تقييم منخفض من مريض (${score}/5 نجوم)!</b>

👤 <b>اسم المريض:</b> ${patientName}
📞 <b>رقم الهاتف:</b> <code>+${patientPhone}</code>
🔢 <b>رقم الحجز:</b> #${appointmentId}
⭐ <b>التقييم المختار:</b> ${score} من 5

📲 <a href="${waLink}">اضغط هنا للتواصل مع المريض فوراً وحل المشكلة</a>`;

  return [{
    json: {
      score: score,
      appointment_id: appointmentId,
      patient_phone: patientPhone,
      phone_number_id: cfg.phone_number_id,
      meta_access_token: cfg.meta_access_token,
      telegram_bot_token: cfg.telegram_bot_token,
      telegram_chat_id: cfg.telegram_chat_id,
      is_low_rating_alert: true,
      customer_reply_text: replyToCustomer,
      admin_telegram_alert: adminAlertHtml
    }
  }];
}
